package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamThalaLayaBank2 {
    private const val T = "තාල පද්ධතිය, මාත්‍රා, ලයකාරී හා ස්වරලිපි"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("කිසියම් තාලයක 'තනි ගුණය' හෙවත් මූලික රිද්ම වේගය හඳුන්වන්නේ කුමන නමින්ද?", "ඨාහ් ලය", "දුගුන් ලය", "තිගුන් ලය", "චෞගුන් ලය", "එක් මාත්‍රාවකට එක් බෝල් පදයක් ගැළපෙන මූලික වේගය ඨාහ් ලයයි."),
        q("තාල සටහනකදී 'ස - ප ධ -' ලෙස සඳහන් වන විට මුළු ස්වර ඛණ්ඩය සඳහා ගත වන මාත්‍රා ගණන කීයද?", "මාත්‍රා 4 කි", "මාත්‍රා 2 කි", "මාත්‍රා 6 කි", "මාත්‍රා 8 කි", "ස(1) + -(1) + ප ධ(වක්‍ර නැති නම් 2) ලෙස ස(1)+-(1)+ප(1)+-(1) හෝ එක් එක් අක්ෂරය/ඉර මාත්‍රා 1 බැගින් 4කි."),
        q("සමපදි තාලයක් වන ත්‍රිතාලයේ සෑම විභාගයකම අඩංගු මාත්‍රා සංඛ්‍යාව කොපමණද?", "මාත්‍රා 4 කි", "මාත්‍රා 2 කි", "මාත්‍රා 3 කි", "මාත්‍රා 6 කි", "4 + 4 + 4 + 4 ලෙස විභාග 4ටම මාත්‍රා 4 බැගින් ඇත."),
        q("ඒක්තාලයේදී 'තාලි' සහ 'ඛාලි' මාරුවෙන් මාරුවට පිහිටන ආකාරයෙන් 11 වන මාත්‍රාව කුමක්ද?", "සිව්වන තාලිය (අංක 4)", "දෙවන ඛාලිය (0)", "පළමු තාලිය (සම)", "තෙවන ඛාලිය", "ඒක්තාලයේ 1(X), 3(0), 5(2), 7(0), 9(3), 11(4) ලෙස 11 වන මාත්‍රාව සිව්වන තාලියයි."),
        q("තබ්ලාවක චෞතාලය වාදනය කරන විට මාත්‍රා බෙදීම කෙසේ සිදුවේද?", "2 + 2 + 2 + 2 + 2 + 2", "4 + 4 + 4 + 4", "3 + 2 + 2", "5 + 2 + 3 + 4", "චෞතාලය ඒක්තාලය මෙන්ම මාත්‍රා 2 බැගින් වූ අංග 6කට බෙදේ."),
        q("ධෲපද් ගායනය සඳහා යොදන 'චෞතාලය' සහ ඛයාල් සඳහා යොදන 'ඒක්තාලය' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "චෞතාලයේ ඛුලේ බෝල් (පඛාවජ්) යෙදෙන අතර ඒක්තාලයේ බන්ද් බෝල් (තබ්ලා) යෙදේ", "චෞතාලය මාත්‍රා 8ක් වන අතර ඒක්තාලය මාත්‍රා 16කි", "චෞතාලයේ ඛාලි නැති අතර ඒක්තාලයේ ඛාලි 4ක් ඇත", "චෞතාලය ජන කවිවලටද ඒක්තාලය නාඩගම්වලටද යෙදේ", "දෙකම මාත්‍රා 12 හා 1,5,9,11 තාලි, 3,7 ඛාලි ඇති මුත් බෝල් ශෛලිය හා වාද්‍ය භාණ්ඩ වෙනස් වේ."),
        q("මාත්‍රා 14 ක් ඇති ධමාර් තාලයේ ඛාලිය ('0') පිහිටන්නේ කීවෙනි මාත්‍රාවේද?", "8 වන මාත්‍රාවේ", "5 වන මාත්‍රාවේ", "6 වන මාත්‍රාවේ", "11 වන මාත්‍රාවේ", "5+2+3+4 බෙදීම අනුව 1(X), 6(2), 8(0), 11(3) ලෙස 8 වන මාත්‍රාව ඛාලිය වේ."),
        q("දීප්චන්දි තාලයේ (මාත්‍රා 14) ඛාලිය පිහිටන මාත්‍රාව කුමක්ද?", "8 වන මාත්‍රාව", "4 වන මාත්‍රාව", "11 වන මාත්‍රාව", "6 වන මාත්‍රාව", "3+4+3+4 බෙදීම අනුව 1(X), 4(2), 8(0), 11(3) ලෙස 8 වන මාත්‍රාව ඛාලිය වේ."),
        q("ඣූම්රා තාලයේ (Jhoomra) මුළු මාත්‍රා සංඛ්‍යාව සහ විභාග බෙදීම කුමක්ද?", "මාත්‍රා 14 (3 + 4 + 3 + 4)", "මාත්‍රා 12 (4 + 4 + 4)", "මාත්‍රා 16 (4 + 4 + 4 + 4)", "මාත්‍රා 10 (2 + 3 + 2 + 3)", "විලම්බිත ඛයාල් සඳහා යොදන ඣූම්රා තාලය දීප්චන්දි මෙන් 3+4+3+4 බෙදීම දරයි."),
        q("තාල පද්ධතියේ 'කායදා' (Kayda) යන තබ්ලා වාදන අංගයේ ස්වභාවය කුමක්ද?", "නියමිත බෝල් සමූහයක් විවිධ ප්‍රස්තාර හෙවත් පල්ටා ලෙස ව්‍යාප්ත කර වැයීම", "එක්වරක් පමණක් ගසා නවත්වන කෙටි හඬක්", "ගීතයේ සාහිත්‍ය වචන පමණක් ගැයීම", "බටහිර ස්ටාෆ් සටහන පිටපත් කිරීම", "කායදා යනු තබ්ලා තනි වාදනයේ නීතිගත ප්‍රස්තාර මූලයයි."),
        q("තබ්ලා වාදනයේදී 'පේෂ්කාර්' (Peshkar) ඉදිරිපත් කරනු ලබන්නේ තනි වාදනයක කුමන අවස්ථාවේදීද?", "ආරම්භයේදී විලම්බිත ලයෙන්", "අවසානයේදී අති වේගවත්ව", "ගීතයක් අතරතුර ඛාලි විරාමයේදී", "නාට්‍ය දෙබසකින් පසුව පමණි", "තබ්ලා සෝලෝ ආරම්භයේදී ප්‍රේක්ෂකයා රිද්මයට හුරු කිරීමට පේෂ්කාර් වයයි."),
        q("තබ්ලා වාදනයේදී සෘජුවම ඉතා ජවසම්පන්න බෝල් සහිතව වයා තිහායියකින් අවසන් කරන කෙටි අංගය කුමක්ද?", "තුක්ඩා (Tukda) හෝ පරන්", "ඨේකාව", "අලාපය", "මීණ්ඩ්", "තුක්ඩා යනු කෙටි, ආකර්ෂණීය වාදන කැබැල්ලකි."),
        q("තබ්ලා වාදනයේදී මුළු දෑතින්ම එක්වර දායා සහ බායා මත වයන 'ධින්' බෝලය අවශ්‍ය වන්නේ කුමන තාලයක 2 වන මාත්‍රාවටද?", "ත්‍රිතාලය සහ ඒක්තාලය", "රූපක් තාලය", "දාද්‍රා තාලය", "ඛහර්වා තාලය", "ත්‍රිතාලය 'ධා ධින්...' හා ඒක්තාලය 'ධින් ධින්...' ලෙස 2 වන මාත්‍රාවේ ධින් යෙදේ."),
        q("ලයකාරි ගණනය කිරීමේදී 'ආඩ්' (Aad) ලය හෙවත් තෙවැනි භාගික ලයෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "මාත්‍රා 2 ක කාලය තුළ අක්ෂර 3 ක් (1.5 බැගින්) උච්චාරණය කිරීම", "මාත්‍රා 1 කට අක්ෂර 4 ක් කීම", "මාත්‍රා 4 කට අක්ෂර 1 ක් කීම", "මාත්‍රාව සම්පූර්ණයෙන් නිහඬ කිරීම", "ආඩ් ලය 3/2 හෙවත් මාත්‍රා දෙකකට බෝල් තුනක් බෙදෙන වක්‍ර රිද්මයයි."),
        q("භාත්ඛණ්ඩේ ස්වරලිපියේදී ස්වර 3 ක් හෝ 4 ක් එකට බැඳ එක් මාත්‍රාවකට ගත යුතු විට ඊට යටින් අඳින්නේ කුමක්ද?", "අර්ධ වෘත්තාකාර වක්‍ර චාපයක්", "ද්විත්ව සෘජු රේඛාවක්", "කුඩා කතිර දෙකක්", "විශාල බිංදුවක්", "උදාහරණ ලෙස (සරිගම) යටින් වක්‍ර රේඛාවක් දමා ඒවා එක් මාත්‍රාවකට ගනී."),
        q("බටහිර සංගීතයේ පංච රේඛකයේ පහළ සිට ඉහළට ඇති රේඛා 5 මත ට්‍රෙබල් ක්ලෙෆ් යටතේ පිහිටන ස්වර අනුපිළිවෙළ කුමක්ද?", "E, G, B, D, F", "F, A, C, E, G", "G, B, D, F, A", "C, D, E, F, G", "Treble Staff රේඛා පහේ පිළිවෙළ පහළ සිට ඉහළට E - G - B - D - F වේ."),
        q("බටහිර පංච රේඛකයේ ට්‍රෙබල් ක්ලෙෆ් යටතේ රේඛා අතර ඇති හිඩැස් (Spaces) 4 පහළ සිට ඉහළට දක්වන ස්වර මොනවාද?", "F, A, C, E", "E, G, B, D", "A, C, E, G", "D, F, A, C", "Treble Staff හිඩැස් 4 පිළිවෙළින් F-A-C-E ('FACE') වචනය මෙන් මතක තබා ගනී."),
        q("බටහිර සංගීතයේදී 'Crotchet' ස්වර දෙකක කාලය එකතු වූ විට සෑදෙන තනි ස්වර සංකේතය කුමක්ද?", "මිනිම් (Minim - මාත්‍රා 2)", "සෙමිබ්‍රේව් (Semibreve - මාත්‍රා 4)", "ක්වේවර් (Quaver - මාත්‍රා 1/2)", "සෙමික්වේවර් (Semiquaver - මාත්‍රා 1/4)", "1 + 1 = 2 මාත්‍රා වන බැවින් එය මිනිම් සංකේතයට සමාන වේ."),
        q("බටහිර සංගීතයේදී 'Quaver' ස්වර හතරක් එකතු වූ විට ලැබෙන මුළු බීට් ගණන කොපමණද?", "බීට් 2 කි (මාත්‍රා 2)", "බීට් 4 කි", "බීට් 1 කි", "බීට් 8 කි", "එක් ක්වේවරයක් 1/2 බීට් බැවින් 4 × 1/2 = බීට් 2 කි."),
        q("බටහිර ස්වරලිපියේදී නිහඬ කාලයක් (විරාමයක්) දැක්වීම සඳහා භාවිත කරන සංකේත හඳුන්වන්නේ කුමන නමින්ද?", "රෙස්ට් (Rest Symbols)", "ක්ලෙෆ් (Clef Symbols)", "ටයි (Tie Symbols)", "ස්ලර් (Slur Symbols)", "ශබ්දය නොනඟවා නියමිත මාත්‍රා ගණන රැඳී සිටීමට Rest සංකේත යොදයි."),
        q("පෙරදිග සංගීතයේ 'මාත්‍රා 16' සහිත ත්‍රිතාලය වේගයෙන් (ද්‍රුත ලයෙන්) වැයීමේදී බහුලව යොදාගන්නේ කුමන ගායනය සඳහාද?", "චෝටා ඛයාල් සහ තාරානා", "විලම්බිත ධෲපද්", "රාත්‍රී පැල් කවි", "අනියත අලාප", "ද්‍රුත ත්‍රිතාලය චෝටා ඛයාල්, තාරානා හා සිතාර් රසාඛානි ගත් සඳහා යොදයි."),
        q("සිතාර් හෝ සරෝද් වාදනයේදී ත්‍රිතාලයේ 12 වන මාත්‍රාවේ සිට ආරම්භ වන මුඛ්ඩාවක් සම මතට එන විට ගත වන මාත්‍රා ගණන කීයද?", "මාත්‍රා 5 ක්", "මාත්‍රා 16 ක්", "මාත්‍රා 2 ක්", "මාත්‍රා 10 ක්", "රසාඛානි ගත් බොහෝ විට 12 වන මාත්‍රාවෙන් ඇරඹී 5 මාත්‍රාවකින් 1 (සම) මත රැඳේ."),
        q("තාල සටහනක් තුළ 'ස රි ග' ලෙස වක්‍ර චාපයක් යටින් තබා එක් මාත්‍රාවක ලියා ඇත්නම් එය සමාන වන්නේ කුමන ලය ගුණයකටද?", "තිගුන් (තෙගුණය)", "දුගුන් (දෙගුණය)", "චෞගුන් (සිව් ගුණය)", "ඨාහ් (ඒක ගුණය)", "එක් මාත්‍රාවක් තුළ ස්වර තුනක් ඇති බැවින් එය තෙගුණ වේගයකින් ගැයේ."),
        q("කිසියම් තාලයක 'සම' සලකුණ අසල '1' යනුවෙන් නොලියා 'X' ලකුණ යෙදීමට හේතුව කුමක්ද?", "සම සෙසු තාලිවලින් වෙන් කොට ප්‍රධාන ආරම්භය ලෙස හඳුනා ගැනීමට", "පළමු මාත්‍රාවේදී නිහඬව සිටිය යුතු බව දැක්වීමට", "පළමු මාත්‍රාව වැරදි මාත්‍රාවක් බව පෙන්වීමට", "තාලයේ අවසානය දැක්වීමට", "X මඟින් මුළු රිද්ම චක්‍රයේම ප්‍රධාන කේන්ද්‍රය ක්ෂණිකව පෙනී යයි."),
        q("තාලයක ඨේකාව 'ඛාලි' වලින් හඳුනාගැනීමේදී තබ්ලාවේ වාදනය අඩු වන්නේ කුමන අතින්ද?", "වම් අතින් (බායා බෙරයෙන්)", "දකුණු අතින් (දායා බෙරයෙන්)", "දෑතින්ම එකවර", "ඇඟිලිවලින් පමණක්", "ඛාලි කොටසේදී බායා බෙරයේ ගැඹුරු බේස් හඬ නොවැයී සැහැල්ලු හඬක් එයි."),
        q("ඛහර්වා තාලයේ 5 සිට 8 දක්වා මාත්‍රා ඛාලි විභාගයට අයත් වන්නේ ඇයි?", "5 වන මාත්‍රාවේ '0' ලකුණ ඇති බැවිනි", "1 වන මාත්‍රාවේ '0' ලකුණ ඇති බැවිනි", "4 වන මාත්‍රාවේ 'X' ලකුණ ඇති බැවිනි", "8 වන මාත්‍රාවේ '3' ලකුණ ඇති බැවිනි", "4 + 4 බෙදීමේ දෙවන අංගය 5, 6, 7, 8 මාත්‍රාවලින් සමන්විත ඛාලි කොටසයි."),
        q("දාද්‍රා තාලයේ බෝල් පෙළ දුගුන් (දෙගුණ) වේගයෙන් කියවන විට එක් ආවර්තනයක (මාත්‍රා 6) මුළු බෝල් අක්ෂර ගණන කීයද?", "12 කි", "6 කි", "18 කි", "24 කි", "මාත්‍රා 6 × 2 = බෝල් 12 ක් එක් ආවර්තනයක යෙදේ."),
        q("ත්‍රිතාලයේ චෞගුන් (සිව් ගුණ) ගායනයේදී හෝ වාදනයේදී මාත්‍රා 16 ක ආවර්තනයක අඩංගු බෝල් ප්‍රමාණය කොපමණද?", "64 කි", "32 කි", "16 කි", "48 කි", "16 × 4 = 64 බෝල් අක්ෂර සංඛ්‍යාවක් චෞගුන්හිදී පිහිටයි."),
        q("රූපක් තාලයේ ආවර්තන දෙකක් සම්පූර්ණ වීමට ගත වන මුළු මාත්‍රා සංඛ්‍යාව කොපමණද?", "මාත්‍රා 14 කි", "මාත්‍රා 7 කි", "මාත්‍රා 21 කි", "මාත්‍රා 12 කි", "එක් ආවර්තනයකට මාත්‍රා 7 බැගින් ආවර්තන 2ට මාත්‍රා 14ක් ගත වේ."),
        q("ඣප්තාලයේ ආවර්තන තුනක් අවසන් කිරීමේදී ගණනය වන මුළු මාත්‍රා ප්‍රමාණය කොපමණද?", "මාත්‍රා 30 කි", "මාත්‍රා 20 කි", "මාත්‍රා 10 කි", "මාත්‍රා 24 කි", "එක් ආවර්තනයකට මාත්‍රා 10 බැගින් ආවර්තන 3ට 30ක් වේ."),
        q("මාත්‍රා 16 කින් යුත් ත්‍රිතාලයේ එක් ආවර්තනයක දුගුන්, තිගුන් හා චෞගුන් අතුරින් වඩාත්ම වේගවත් ලයකාරිය කුමක්ද?", "චෞගුන්", "තිගුන්", "දුගුන්", "ඨාහ්", "මාත්‍රාවට අක්ෂර 4 බැගින් වැයෙන චෞගුන් වඩාත් වේගවත්ය."),
        q("විලම්බිත ලයේදී ගායකයෙකු ගීතයක් ගයන විට ගීතයේ අන්තරාව අවසන් කර නැවත සමට ළඟා වීමට කුමන ලක්ෂණය රැකගත යුතුද?", "නියත හෘද ස්පන්දන ලෙස සමාන මාත්‍රා පරතරය රැකීම", "මාත්‍රා කිහිපයක් අත්හැර වේගයෙන් දිවීම", "තබ්ලා වාදකයා නැවැත්වීම", "කෝමල ස්වර අත්හැරීම", "මාත්‍රා අතර සමාන කාලය රැකීමෙන් තොරව නිවැරදි සම ලැබිය නොහැක."),
        q("තාල සටහනකදී 'ධා ගේ න තිං | න ක ධින් නා' යන බෝල් අට අතරින් සම මත වැයෙන පළමු බෝලය කුමක්ද?", "ධා", "න", "තිං", "නා", "ඛහර්වා තාලයේ 1 වන මාත්‍රාව හෙවත් සම මත 'ධා' වැයේ."),
        q("රූපක් තාලයේදී 'තින් තින් නා | ධී නා | ධී නා' අතරින් පළමු ඛාලිය ('0') වැයෙන බෝලය කුමක්ද?", "තින් (1 වන මාත්‍රාව)", "ධී (4 වන මාත්‍රාව)", "නා (3 වන මාත්‍රාව)", "ධී (6 වන මාත්‍රාව)", "රූපක් තාලය ආරම්භ වන්නේ 1 වන මාත්‍රාවේ ඛාලි 'තින්' බෝලයෙනි."),
        q("ඣප්තාලයේ 'ධී නා | ධී ධී නා | තී නා | ධී ධී නා' යන ඨේකාවේ 6 වන මාත්‍රාව වන ඛාලියේදී වැයෙන බෝලය කුමක්ද?", "තී", "ධී", "නා", "ධා", "1(ධී), 2(නා), 3(ධී), 4(ධී), 5(නා), 6(තී - ඛාලි) ලෙස 6 වන මාත්‍රාවේ 'තී' වැයේ."),
        q("ඒක්තාලයේදී (මාත්‍රා 12) 'ධින් ධින් | ධාගේ තිරිකිට' යන පළමු මාත්‍රා හතර තුළ 3 වන මාත්‍රාවට අයත් බෝලය කුමක්ද?", "ධාගේ", "ධින්", "තිරිකිට", "තූ", "3 වන මාත්‍රාවේ ඛාලි (හෝ පළමු බෝල යුගලය) ලෙස 'ධාගේ' සටහන් වේ."),
        q("සංගීතයේ 'බරෝබර් ලය' යන වචනයෙන් හඳුන්වන්නේ කුමන ලය ගුණයද?", "ඨාහ් හෙවත් ඒක ගුණය", "දුගුන් හෙවත් දෙගුණය", "තිගුන් හෙවත් තෙගුණය", "චෞගුන් හෙවත් සිව් ගුණය", "සමාන මාත්‍රා වේගය බරෝබර් ලය හෙවත් ඨාහ් ලය ලෙස හඳුන්වයි."),
        q("බටහිර සංගීතයේදී Crotchet (1) + Minim (2) + Quaver (1/2) යන කාලයන්ගේ එකතුව කොපමණද?", "බීට් 3.5 කි", "බීට් 4 කි", "බීට් 2.5 කි", "බීට් 5 කි", "1 + 2 + 0.5 = 3.5 මාත්‍රා ප්‍රමාණයක් මෙයින් ලැබේ."),
        q("බටහිර සංගීතයේදී ස්වර ලකුණක් අසලින්ම කුඩා තිතක් (Dot) තැබූ විට එම ස්වරයේ කාලයට සිදු වන්නේ කුමක්ද?", "මුල් කාලයෙන් අඩක් එම ස්වරයට එකතු වේ", "මුල් කාලය දෙකෙන් බෙදේ", "ස්වරය මන්ද්‍ර සප්තකයට වැටේ", "ස්වරය නිහඬ වේ", "Dotted Minim = 2 + 1 = බීට් 3 ක් වන සේ තිතෙන් මුල් කාලයෙන් 50%ක් එක් වේ."),
        q("බටහිර ස්වරලිපියේදී Dotted Crotchet (තිතක් සහිත ක්‍රොචට්) එකක මුළු බීට් කාලය කොපමණද?", "බීට් 1.5 කි", "බීට් 3 කි", "බීට් 2 කි", "බීට් 0.75 කි", "Crotchet (1) + අඩ (0.5) = 1.5 බීට් කාලයක් දරයි."),
        q("දේශීය ගීතයක ස්වරලිපි සටහන් කිරීමේදී මධ්‍ය සප්තකයේ ස්වර මුදුනේ හෝ පහළින් තිත් නොදමන්නේ ඇයි?", "මධ්‍ය සප්තකය සාමාන්‍ය මූලික පරාසය ලෙස වෙන් කර ගැනීමට", "මධ්‍ය සප්තකය ගායනා නොකරන නිසා", "මධ්‍ය සප්තකයේ විකෘති ස්වර නැති නිසා", "තාල සංකේතවලට බාධා නොවන නිසා", "තිත් රහිතව ලිවීම මධ්‍ය සප්තකය පහසුවෙන් කියවීමේ ක්‍රමයයි."),
        q("සංගීත ප්‍රායෝගික පරීක්ෂණයේදී තාල තැබීමේ විශේෂත්වය වන්නේ කුමක්ද?", "සම, තාලි සහ ඛාලි නිවැරදි අත් අභිනයෙන් පෙන්වීම", "බෙරය මත හිඳගෙන අත්පුඩි ගැසීම", "කතා නොකර සිටීම", "තාලයේ මාත්‍රා සංඛ්‍යාව අමතක කිරීම", "පැහැදිලි හඬින් බෝල් කියමින් අත්තාලය නිවැරදිව දැක්වීම පරීක්ෂා කෙරේ."),
        q("සිසුවෙකුට භූපාලි රාගයේ ස්ථායි ස්වරලිපිය කියවා ගැයීමට ලබා දුන් විට 'X' සංකේතය යට ඇති ස්වරය කෙසේ ගැයිය යුතුද?", "තාලයේ සම ස්ථානය මත තබා ප්‍රමුඛව ගැයීම", "එම ස්වරය අත්හැර ඊළඟ ස්වරය ගැයීම", "විකෘති ස්වරයක් බවට හැරවීම", "නතර කර ආචාර කිරීම", "ස්වරලිපියේ X යනු තාලයේ සම ස්ථානය වන බැවින් ගීතයේ ප්‍රධාන තාල පහර එහි වැටේ."),
        q("භාත්ඛණ්ඩේ ස්වරලිපියේදී ස්වර කණ්ඩයක් මත 'ධා ධින්...' වැනි තබ්ලා බෝල් දක්වා නැති වුවද තාලය හඳුනා ගත හැක්කේ කුමකින්ද?", "X, 0, 2, 3 වැනි තාල සංකේත හා මාත්‍රා විභාග රේඛාවලින්", "රාගයේ වාදී ස්වරයේ නමින්", "ගායකයාගේ නමින්", "වාද්‍ය භාණ්ඩයේ වර්ගයෙන්", "මාත්‍රා ගණන හා විභාග සැකිල්ල අනුව ඕනෑම තාලයක් වහා හඳුනාගත හැකිය."),
        q("මාත්‍රා 16 ක් (4+4+4+4) ඇති ත්‍රිතාලය සහ මාත්‍රා 8 ක් (4+4) ඇති ඛහර්වා තාලය අතර ඇති සමානකම කුමක්ද?", "විභාග සියල්ල මාත්‍රා 4 බැගින් බෙදී පැවතීම", "දෙකෙහිම ඛාලි 4 බැගින් තිබීම", "දෙකම පඛාවජයෙන් පමණක් වැයීම", "දෙකෙහිම 1 වන මාත්‍රාව ඛාලි වීම", "දෙකම චතුරශ්‍ර ජාතියේ 4 බැගින් විභාග බෙදෙන තාල වේ."),
        q("දාද්‍රා තාලයේ ඛාලි විභාගය ආරම්භ වන්නේ කීවෙනි මාත්‍රාවෙන්ද?", "4 වන මාත්‍රාවෙන්", "1 වන මාත්‍රාවෙන්", "3 වන මාත්‍රාවෙන්", "6 වන මාත්‍රාවෙන්", "1, 2, 3 (පළමු අංගය) ගෙවී 4 වන මාත්‍රාවේ ඛාලි ('0') ඇරඹේ."),
        q("කිසියම් සරල ගීයක රිද්මය මාත්‍රා 3 බැගින් වූ වේගවත් ගැස්මකින් යුක්ත නම් ඊට වඩාත් ගැළපෙන තාලය කුමක්ද?", "දාද්‍රා තාලය", "ත්‍රිතාලය", "ඒක්තාලය", "චෞතාලය", "3+3 ලෙස තිශ්‍ර ගතියෙන් ගමන් කරන්නේ දාද්‍රා තාලයයි."),
        q("බටහිර 6/8 කාල සංකේතයේ ඇති මුළු අෂ්ටම ස්වර (Quavers) සංඛ්‍යාව කොපමණද?", "6 කි (3+3 කාණ්ඩ දෙකක්)", "8 කි", "4 කි", "12 කි", "6/8 තාලයේ එක් කොටුවක ක්වේවර් 6ක් (සංයුක්ත ද්විත්ව රිද්මයක් ලෙස) පිහිටයි."),
        q("මන්දගාමීව සිහිල් භාවයෙන් රාගයක් ගයන විට ගායකයා තෝරාගත යුතු වඩාත් සුදුසු ලය කුමක්ද?", "විලම්බිත ලය", "ද්‍රුත ලය", "චෞගුන් ලය", "අතිද්‍රුත ලය", "ගැඹුරු භාවපූර්ණ විස්තාරය සඳහා විලම්බිත ලය වඩාත් සුදුසුය."),
        q("සංගීතයේ 'ඨාහ්, දුගුන්, චෞගුන්' යන පියවර තුන අනුපිළිවෙළින් පෙළගැස්වූ විට සිදුවන්නේ කුමක්ද?", "මාත්‍රාවකට ඇති බෝල් සංඛ්‍යාව 1 සිට 2 ට සහ 4 ට දෙගුණ වෙමින් ඉහළ යාම", "ලය ක්‍රමයෙන් මන්දගාමී වී නැවතීම", "ස්වර මන්ද්‍ර සප්තකයට වැටීම", "තාලයේ මාත්‍රා ගණන අඩු වීම", "1×, 2×, 4× වශයෙන් රිද්ම ඝනත්වය දෙගුණ වෙමින් ගමන් කරයි."),
        q("තාල සටහනක ස්වර 2ක් එක් මාත්‍රාවක් තුළ දක්වා 'සරි' ලෙස වක්‍ර රේඛාවක් යොදා ඇත්නම් එක් ස්වරයකට හිමි කාලය කොපමණද?", "මාත්‍රා 1/2 ක් බැගින්", "මාත්‍රා 2 ක් බැගින්", "මාත්‍රා 1 ක් බැගින්", "මාත්‍රා 1/4 ක් බැගින්", "මාත්‍රා 1 ස්වර 2කට බෙදෙන විට එක් ස්වරයක් 1/2 මාත්‍රාවක් වේ."),
        q("භාත්ඛණ්ඩේ ස්වරලිපියේදී 'ග ම ප ධ' යන ස්වර හතරම එක් වක්‍ර චාපයක් තුළ දක්වා ඇති විට එක් ස්වරයකට හිමි මාත්‍රා කාලය කුමක්ද?", "මාත්‍රා 1/4 කි", "මාත්‍රා 1/2 කි", "මාත්‍රා 1 කි", "මාත්‍රා 4 කි", "මාත්‍රා 1ක් සමාන කොටස් 4කට බෙදෙන විට ස්වරයක් 1/4 කාලය ගනී."),
        q("තාල පද්ධතිය තුළ 'සම' ස්ථානය වරදවා වෙනත් මාත්‍රාවක ගීතයේ මුඛ්ඩාව අවසන් කළහොත් ඇති වන්නේ කුමක්ද?", "තාල භංගය (තාලය බිඳී යාම)", "රාග සිද්ධිය", "ශ්‍රැති සමපාතය", "සර්ගම් සමතුලිතතාව", "සම මගහැරීමෙන් තබ්ලාව සහ ගායනය අතර සමමුහුර්තතාව බිඳී යයි."),
        q("සිංහල ජන සංගීතයේ එන 'දවුල' හෝ 'ගැටබෙරය' වාදනය කිරීමේදී යොදාගන්නා මූලික රිද්ම අක්ෂර හඳුන්වන්නේ කුමන නමින්ද?", "බෙර පද / වට්ටම්", "රාග පකඩ", "විකෘති ස්වර", "ස්ටාෆ් සටහන්", "දේශීය බෙර සම්ප්‍රදායේ රිද්ම ඛණ්ඩ බෙර පද හෙවත් වට්ටම් ලෙස හැඳින්වේ."),
        q("බටහිර 2/4 කාල සංකේතය අනුව එක් කොටුවක් තුළ පවතින ක්‍රොචට් (Crotchet) ගණන කීයද?", "2 කි", "4 කි", "3 කි", "8 කි", "ඉහළ අංකය 2 වන අතර පහළ අංකය 4 (Crotchet) දක්වන බැවින් කොටුවක ක්‍රොචට් 2කි."),
        q("තබ්ලාවේ වම් බෙරය වන 'බායා' වාදනය කරන විට මැණික් කටුව ඉදිරියට ලිස්සා යවමින් නිකුත් කරන ගැඹුරු ලිස්සන නාදය කුමක්ද?", "මීණ්ඩ් / ගමක් නාදය (ඝීස්)", "චාන්ටි නාදය", "තිට් නාදය", "නා බෝලය", "බායා සම මත අත්ල තද කර ඉදිරියට ලිස්සා හැරීමෙන් මධුර ඝීස් නාදය නැගේ."),
        q("පෙරදිග සංගීතයේ තාලයක් ප්‍රගුණ කිරීමේදී ශිෂ්‍යයෙකු මුලින්ම කළ යුතු නිවැරදි පුහුණු පියවර කුමක්ද?", "අතෙන් තාලි-ඛාලි තබමින් මුඛයෙන් ඨේකා බෝල් නිවැරදි ලයට උච්චාරණය කිරීම", "අති වේගවත්ව චෞගුන් පමණක් ගැයීම", "බෙරය නොසලකා ස්වර පමණක් කියවීම", "තාල සංකේත මකා දමා ගැයීම", "අත් තාලය (පඩ්හන්ත්) මඟින් මාත්‍රා ඒකාකාරව මනසේ ස්ථාපිත වේ."),
        q("පහත දැක්වෙන කුමන තාලයක 1 සිට 12 දක්වා මාත්‍රා 2 බැගින් වූ විභාග 6ක් ඇති වුවත් ඛාලි 2ක් හා තාලි 4ක් පවතීද?", "ඒක්තාලය (සහ චෞතාලය)", "ත්‍රිතාලය", "රූපක් තාලය", "දාද්‍රා තාලය", "ඒක්තාලයේ 1,5,9,11 තාලි 4ක්ද 3,7 ඛාලි 2ක්ද ඇතිව විභාග 6ක් වේ."),
        q("සංගීත කණ්ඩායමක් තුළ ගායකයා, සිතාර් වාදකයා සහ තබ්ලා වාදකයා එකට බැඳ තබන ප්‍රධාන සාධක දෙක මොනවාද?", "සමාන ශ්‍රැතිය ('ස') සහ පොදු තාල ලය", "වේදිකා ආලෝකය සහ තිර රෙදි", "නර්තන වෙස්මුහුණු සහ සළු", "සප්තකයේ තාර ස්වර පමණක්", "ශ්‍රැති ඒකාබද්ධතාව සහ තාල සමමුහුර්තතාව ප්‍රසංගයක මූලික පදනමයි."),
        q("සිසුවෙකු ස්වර මාලිකාවක් 'ත්‍රිතාලයෙන්' ප්‍රස්තාර කරන විට පළමු පේළියේ සම්පූර්ණ ආවර්තනය තුළ ලිවිය යුතු මුළු මාත්‍රා ස්ථාන ගණන කීයද?", "මාත්‍රා 16 කි", "මාත්‍රා 12 කි", "මාත්‍රා 8 කි", "මාත්‍රා 10 කි", "ත්‍රිතාල ආවර්තනයක මාත්‍රා 16 සම්පූර්ණයෙන්ම පේළියක හෝ විභාග 4ක සටහන් වේ."),
        q("තාල සටහන් අධ්‍යයනය කිරීමෙන් සංගීත ශිෂ්‍යයාට ලැබෙන ප්‍රායෝගික ප්‍රතිලාභය කුමක්ද?", "ඕනෑම නව ගීතයක ස්වර සහ කාල ප්‍රමාණ නිවැරදිව කියවා ගැයීමට හැකි වීම", "රාගවල වර්ජිත ස්වර වැඩි කිරීමට හැකි වීම", "තම්බුරාව නොමැතිව ගායනා කිරීමට හැකි වීම", "බෙර වාදනය සම්පූර්ණයෙන් අවශ්‍ය නොවීම", "ස්වරලිපි කියවීමේ හැකියාව නිසා සංගීත නිර්මාණ සදාකාලිකව ආරක්ෂා වී හුවමාරු වේ."),
        q("බටහිර සංගීත සටහන් ක්‍රමයේ 'Bar Line' (සිරස් රේඛාව) මඟින් ඉටු කරන කාර්යය පෙරදිග කුමන අංගයට සමානද?", "විභාග බෙදන සිරස් රේඛාවට", "තීව්‍ර මධ්‍යම සලකුණට", "කෝමල ස්වර යටි රේඛාවට", "මන්ද්‍ර තිතට", "බටහිර Bar Line මෙන් පෙරදිග ස්වරලිපියේ විභාග සිරස් රේඛා කාල කොටස් වෙන් කරයි."),
        q("ත්‍රිතාලයේ 9 වන මාත්‍රාවෙන් ආරම්භ වන කොටස හඳුන්වන්නේ කුමන නමින්ද?", "ඛාලි විභාගය", "සම විභාගය", "දෙවන තාලි විභාගය", "තෙවන තාලි විභාගය", "ත්‍රිතාලයේ 1(X), 5(2), 9(0), 13(3) ලෙස 9 වන මාත්‍රාවේ ඛාලි විභාගය ඇරඹේ."),
        q("ත්‍රිතාලයේ 13 වන මාත්‍රාවේ සිට 16 වන මාත්‍රාව දක්වා කොටසෙහි වැයෙන ඨේකා බෝල් පෙළ කුමක්ද?", "තා ධින් ධින් ධා", "ධා ධින් ධින් ධා", "ධා තින් තින් තා", "නා ධින් ධින් නා", "ත්‍රිතාලයේ සිව්වන විභාගය 'තා ධින් ධින් ධා' ලෙස සම වෙත පැමිණේ."),
        q("ඛහර්වා තාලයේ මුළු මාත්‍රා 8 තුළ තාලි සහ ඛාලි පිහිටන්නේ කවර මාත්‍රා අංකවලද?", "1 (X) තාලිය සහ 5 (0) ඛාලිය", "1 (X) තාලිය සහ 3 (0) ඛාලිය", "1 (0) ඛාලිය සහ 5 (X) තාලිය", "1 (X), 4 (2), 7 (0)", "ඛහර්වා 4+4 බෙදීමේදී 1 වන මාත්‍රාවේ සමද 5 වන මාත්‍රාවේ ඛාලිද පවතී."),
        q("දාද්‍රා තාලයේ (මාත්‍රා 6) සම්මත ඨේකා බෝල් මාලාව කුමක්ද?", "ධා ධී නා | ධා තූ නා", "ධා ගේ න තිං | න ක ධින් නා", "තී තී නා | ධී නා | ධී නා", "ධී නා | ධී ධී නා | තී නා | ධී ධී නා", "දාද්‍රා තාලය 3+3 බෙදීමට අනුව 'ධා ධී නා | ධා තූ නා' යනුවෙන් වැයේ."),
        q("රූපක් තාලයේ සමස්ත මාත්‍රා 7 බෙදී පවතින විභාග සැකිල්ල නිවැරදිව දක්වන්නේ කුමක්ද?", "3 + 2 + 2", "2 + 3 + 2", "4 + 3", "2 + 2 + 3", "රූපක් තාලයේ පළමු විභාගයේ මාත්‍රා 3ක්ද දෙවන හා තෙවන විභාගවල මාත්‍රා 2 බැගින්ද ඇත."),
        q("රූපක් තාලය හින්දුස්ථානි තාල පද්ධතියේ සුවිශේෂී තාලයක් ලෙස සැලකෙන්නේ කවර හේතුවක් නිසාද?", "1 වන මාත්‍රාවේදීම ඛාලි (0) සලකුණින් ආරම්භ වන බැවින්", "එහි මාත්‍රා 16ක් තිබෙන බැවින්", "එහි තාලි කිසිවක් නැති බැවින්", "එය ධෲපද් සඳහාම පමණක් යෙදෙන බැවින්", "පළමු මාත්‍රාවේ ඛාලි හා සම එකට සලකන අපූරු ලක්ෂණය රූපක් තාලයේ දැකිය හැකිය."),
        q("ඣප්තාලයේ 10 මාත්‍රා සැකැස්ම අනුව තාලි තුන සහ ඛාලි එක පිහිටන මාත්‍රා අනුපිළිවෙළ කුමක්ද?", "1 (X), 3 (2), 6 (0), 8 (3)", "1 (X), 4 (2), 7 (0), 9 (3)", "1 (X), 5 (2), 9 (0), 13 (3)", "1 (0), 4 (2), 6 (3), 8 (4)", "2 + 3 + 2 + 3 විභාග අනුව 1, 3, 8 තාලිද 6 ඛාලිද වේ."),
        q("ඣප්තාලයේ සම්පූර්ණ විභාග හතර තුළ අඩංගු මාත්‍රා ගණන් පිළිවෙළින් කොපමණද?", "2 + 3 + 2 + 3", "3 + 2 + 3 + 2", "2 + 2 + 3 + 3", "4 + 2 + 4", "ඣප්තාලය මාත්‍රා 2, 3, 2, 3 යන අසම විභාග සතරකින් සමන්විත වේ."),
        q("ඒක්තාලයේ මාත්‍රා 12 තුළ පවතින මුළු විභාග සංඛ්‍යාව සහ තාලි ගණන කොපමණද?", "විභාග 6 ක් සහ තාලි 4 ක්", "විභාග 4 ක් සහ තාලි 3 ක්", "විභාග 3 ක් සහ තාලි 2 ක්", "විභාග 2 ක් සහ තාලි 1 ක්", "මාත්‍රා 2 බැගින් වූ විභාග 6ක 1, 5, 9, 11 තාලි 4ක් හා 3, 7 ඛාලි 2ක් පවතී."),
        q("චෞතාලය (මාත්‍රා 12) සාම්ප්‍රදායිකව ප්‍රසංගයේදී වාදනය කිරීමට යොදාගන්නා ප්‍රධාන වාද්‍ය භාණ්ඩය කුමක්ද?", "පඛාවජය (මෘදංගය)", "හාමෝනියමය", "බන්සූරිය", "තම්බුරාව", "ධෲපද් හා ධමාර් සංගීතයේදී චෞතාලය පඛාවජ බෙරයෙන් වාදනය කෙරේ."),
        q("තාල පද්ධතියේ 'විසමපදි' (Vishamapadi) තාලයක් ලෙස හඳුන්වනු ලබන්නේ කුමන ආකාරයේ තාලයක්ද?", "එක් එක් විභාගයේ මාත්‍රා ගණන එකිනෙකට වෙනස් තාලය", "සෑම විභාගයකම මාත්‍රා ගණන සමාන තාලය", "මාත්‍රා නොමැති ගීත රටාව", "තාලි කිසිවක් නැති තාලය", "2+3+2+3 (ඣප්තාල) හෝ 3+2+2 (රූපක්) මෙන් අසමාන විභාග ඇති තාල විසමපදි වේ."),
        q("'ආවර්තනය' (Avartan) යනු තාල ශාස්ත්‍රයේදී කවර ක්‍රියාවලියක්ද?", "1 වන මාත්‍රාවේ සිට අවසන් මාත්‍රාව දක්වා සම්පූර්ණ එක් තාල චක්‍රයක්", "ස්වරයක් තාර සප්තකයට ගෙන යාම", "තබ්ලාවේ සියාහි ආලේප කිරීම", "ගීතයේ අවසන් පදය අත්හැරීම", "තාලයේ සියලුම විභාග හරහා සම සිට සම දක්වා එක් වරක් ගමන් කිරීම ආවර්තනයයි."),
        q("සංගීත සටහනක 'විශ්‍රාම ලකුණ' (Avagraha / -) යෙදූ විට ගායකයා කළ යුත්තේ කුමක්ද?", "පෙර ස්වරයේ හෝ පදයේ නාදය එම මාත්‍රාව පුරාම දීර්ඝ කර රඳවා ගැනීම", "සම්පූර්ණයෙන්ම හඬ නවතා නිහඬ වීම", "තාලයේ වේගය දෙගුණ කිරීම", "කෝමල ස්වරය ශුද්ධ කිරීම", "භාත්ඛණ්ඩේ ක්‍රමයේ '-' මගින් පූර්ව ස්වරයේ දීර්ඝ කිරීම නිරූපණය කරයි."),
        q("තාල සටහනකදී පේළි දෙකක් හෝ තුනක් අවසානයේ පිහිටි 'සම' සලකුණෙන් හෙළි වන්නේ කුමක්ද?", "සෑම ආවර්තනයක්ම එම ප්‍රමුඛ ලක්ෂ්‍යයට පැමිණ සම්පූර්ණ වන බව", "තාලය එතැනින් අවසන් වී වෙනත් රාගයක් ඇරඹෙන බව", "තබ්ලාවේ ශබ්දය අඩු කළ යුතු බව", "ගායකයා නතර විය යුතු බව", "සම යනු සමස්ත තාල ප්‍රවාහයේ කේන්ද්‍රීය හමුවීමේ ලක්ෂ්‍යයයි."),
        q("තිහායි (Tihai) යනු තාල විද්‍යාවේදී කවර ආකාරයේ රිද්ම සංයෝජනයක්ද?", "එකම බෝල් හෝ ස්වර කණ්ඩයක් තුන්වරක් වයා හරියටම සම මත අවසන් කිරීම", "එක් මාත්‍රාවකට බෝල් අටක් කීම", "ගීතය මැදදී ලය නතර කිරීම", "බෙරයේ වම් ඇස පමණක් වැයීම", "තබ්ලා සෝලෝ හා ගායනයේදී තෙවරක් පුනරුච්චාරණය කර සම අල්ලන අලංකාරය තිහායි වේ."),
        q("භාත්ඛණ්ඩේ ස්වරලිපි ක්‍රමයේදී ගීතයේ පදමාලාව (සාහිත්‍යය) ලියා දක්වන්නේ කොතැනද?", "අදාළ ස්වර පේළියට හරියටම යටින්", "පිටුවේ ඉහළම කෙළවරේ පමණක්", "තබ්ලා බෝල්වලට උඩින්", "වෙනම පිටුවක පසුපස", "එක් එක් ස්වරයට හිමි ගීත වචන මාත්‍රා පෙළ අනුව ස්වරයට කෙළින්ම යටින් සටහන් කෙරේ."),
        q("බටහිර සංගීතයේ 4/4 කාල සංකේතය සඳහා බහුලව යොදන විකල්ප අක්ෂර සංකේතය කුමක්ද?", "'C' (Common Time)", "'S' (Simple Time)", "'M' (Major Time)", "'B' (Bass Time)", "බටහිර සංගීත සටහන්වල 4/4 තාලය දැක්වීමට 'C' අක්ෂරය බහුලව භාවිත වේ."),
        q("බටහිර සංගීතයේදී 'Semibreve' ස්වරයකට හිමි සම්පූර්ණ කාල ප්‍රමාණය කොපමණද?", "බීට් 4 කි (Crotchet 4 කට සමාන)", "බීට් 2 කි", "බීට් 1 කි", "බීට් 8 කි", "හතරැස්/අංග සම්පූර්ණ හිස් ඉලිප්සාකාර සෙමිබ්‍රේව් ස්වරය බීට් 4ක් පවතී."),
        q("බටහිර සංගීතයේදී '3/4' කාල සංකේතයෙන් එක් කොටුවක් (Bar) තුළ දැක්වෙන්නේ කුමක්ද?", "Crotchet බීට් 3 ක් ඇති බව", "Minim බීට් 4 ක් ඇති බව", "Quaver බීට් 6 ක් ඇති බව", "Semibreve බීට් 3 ක් ඇති බව", "ඉහළ 3 මගින් බීට් ගණනද පහළ 4 මගින් Crotchet ඒකකයද දක්වයි."),
        q("බටහිර සංගීතයේ Treble Clef සංකේතය තවත් කුමන ස්වර නාමයකින් හඳුන්වනු ලබයිද?", "G Clef", "F Clef", "C Clef", "D Clef", "පහළ සිට දෙවන රේඛාව වන G වටා ඇඳෙන බැවින් එය G Clef නම් වේ."),
        q("බටහිර සංගීතයේ Bass Clef සංකේතය හඳුන්වනු ලබන අනෙක් නාමය කුමක්ද?", "F Clef", "G Clef", "E Clef", "A Clef", "ඉහළ සිට දෙවන රේඛාව වන F වටා තිත් දෙකක් සහිතව ඇඳෙන බැවින් එය F Clef වේ."),
        q("බටහිර ස්ටාෆ් සටහනක ස්වරයක් අසල '#' (Sharp) සංකේතය යොදා ඇත්නම් එයින් සිදුවන්නේ කුමක්ද?", "ස්වරය අර්ධ ස්වරයකින් ඉහළ යාම", "ස්වරය අර්ධ ස්වරයකින් පහළ බැසීම", "ස්වරය සම්පූර්ණයෙන් නිහඬ වීම", "ස්වරයේ කාලය දෙගුණ වීම", "Sharp ලකුණ මගින් මුල් ස්වරය සෙමිටෝනයක් ඉහළ නංවයි."),
        q("බටහිර ස්ටාෆ් සටහනක ස්වරයක් අසල '♭' (Flat) සංකේතය යෙදූ විට එම ස්වරයට සිදු වන්නේ කුමක්ද?", "ස්වරය අර්ධ ස්වරයකින් පහළ බසී (පෙරදිග කෝමල මෙන්)", "ස්වරය අර්ධ ස්වරයකින් ඉහළ යයි", "ස්වරය තාර සප්තකයට මාරු වේ", "තාලයේ වේගය අඩු වේ", "Flat සංකේතයෙන් ස්වරය අර්ධ ස්වරයක් පහළ දමයි."),
        q("පෙරදිග සංගීතයේ කිසියම් තාලයක් 'චතුරශ්‍ර ජාතියෙන්' යුක්ත යැයි කියනු ලබන්නේ කුමන ගණිත රටාව නිසාද?", "4, 8 හෝ 16 ලෙස 4 ගුණාකාර චලනයක් පැවතීම", "3 හෝ 6 ලෙස 3 ගුණාකාර පැවතීම", "5 හෝ 10 ලෙස 5 ගුණාකාර පැවතීම", "7 හෝ 14 ලෙස 7 ගුණාකාර පැවතීම", "ත්‍රිතාල (16) සහ ඛහර්වා (8) මාත්‍රා 4 බැගින් වූ චතුරශ්‍ර චලනයට අයත් වේ."),
        q("තාල සටහනක 'වක්‍ර රේඛාවක්' තුළ ලියූ ස්වර දෙකක් (සරි) යට ගීතයේ එක් අක්ෂරයක් පමණක් තිබේ නම් කුමක් සිදුවේද?", "එම අක්ෂරය මතම ස්වර දෙක ගැයේ (මුර්කි/මීණ්ඩ් සේ)", "දෙවන ස්වරය අත්හැර දැමේ", "අමතර මාත්‍රාවක් එකතු කෙරේ", "වචනය නැවත පටන් ගැනේ", "එක් අක්ෂරයක් දීර්ඝ කරමින් එම කෙටි ස්වර දෙක මාත්‍රා 1 තුළ ගායනා කෙරේ."),
        q("'තින් තින් නා | ධී නා | ධී නා' යන ඨේකාව කියවන විට අත්තාලයෙන් 4 වන මාත්‍රාවේදී කළ යුත්තේ කුමක්ද?", "දෙවන තාලිය (අංක 2) අත්පුඩියෙන් පෙන්වීම", "ඛාලිය ලෙස අත විවෘත කිරීම", "අත පහත හෙළා නිහඬ වීම", "තෙවන තාලිය (අංක 3) ගැසීම", "රූපක් තාලයේ 1(0), 4(2), 6(3) ලෙස 4 වන මාත්‍රාවේ දෙවන තාලිය යෙදේ."),
        q("භාත්ඛණ්ඩේ ස්වරලිපි ක්‍රමයේදී කාල ප්‍රමාණය දැක්වීමට ගීත පද අතර යොදන 'S' හෙවත් අවග්‍රහ ලකුණෙන් කියැවෙන්නේ කුමක්ද?", "පෙර ගීත අක්ෂරයේ ස්වර හඬ දීර්ඝ කිරීම", "නව ගීතයක් ආරම්භ කිරීම", "තබ්ලා වාදනය නැවැත්වීම", "කෝමල ස්වරය වෙනස් කිරීම", "පද පේළියේදී 'S' ලකුණ මගින් අදාළ වචනයේ අවසාන ස්වරය ඇදගෙන යාම දක්වයි."),
        q("සිංහල ගීතයක් හෝ බණ්ඩිසයක් ප්‍රස්තාර කිරීමේදී පළමුවෙන්ම ස්වරලිපියේ මුදුනින්ම සඳහන් කළ යුතු තොරතුරු මොනවාද?", "රාගයේ නම සහ තාලයේ නම", "වාදකයාගේ පාසලේ නම", "ප්‍රසංග ශාලාවේ ලිපිනය", "පොතේ මුද්‍රණ වර්ෂය", "ගීතය කියවන අයෙකුට විකෘති ස්වර සහ මාත්‍රා බෙදීම වටහා ගැනීමට රාගය හා තාලය සඳහන් කළ යුතුය."),
        q("පණ්ඩිත් විෂ්ණු දිගම්බර පලුස්කර් ස්වරලිපි ක්‍රමය සහ භාත්ඛණ්ඩේ ක්‍රමය අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "මාත්‍රා කාලය දැක්වීමට වෙනස් සංකේත භාවිත කිරීම", "ස්වර නාම වෙනස් වීම", "තාල සංඛ්‍යාව වෙනස් වීම", "සප්තක ගණන දහයක් වීම", "පලුස්කර් ක්‍රමයේදී පූර්ණ මාත්‍රා, අඩ මාත්‍රා සඳහා ස්වර යට වෙනස් සලකුණුද සමට '1' ද යොදයි."),
        q("තාල විද්‍යාවේ 'සූලතාලය' (Sooltaal) සඳහා ඇති මුළු මාත්‍රා ගණන සහ විභාග බෙදීම කුමක්ද?", "මාත්‍රා 10 (2 + 2 + 2 + 2 + 2)", "මාත්‍රා 16 (4 + 4 + 4 + 4)", "මාත්‍රා 7 (3 + 2 + 2)", "මාත්‍රා 6 (3 + 3)", "ධෲපද් සඳහා යොදන සූලතාලය මාත්‍රා 2 බැගින් වූ විභාග 5කින් යුක්ත මාත්‍රා 10 තාලයකි."),
        q("තාලයක දුගුන් (දෙගුණ) සටහනක් ලිවීමේදී ත්‍රිතාලයේ එක් මාත්‍රාවක් තුළ ලිවිය යුතු බෝල් ප්‍රමාණය කීයද?", "බෝල් අක්ෂර 2 කි", "බෝල් අක්ෂර 4 කි", "බෝල් අක්ෂර 1 කි", "බෝල් අක්ෂර 3 කි", "දුගුන් යනු මාත්‍රා 1කට අක්ෂර 2 බැගින් කියවන දෙගුණ ලයකාරියයි."),
        q("ලය පිළිබඳ හැදෑරීමේදී මාත්‍රාවකට අක්ෂර භාගයක් (එනම් අක්ෂර 1කට මාත්‍රා 2ක්) ගත වන මන්දගාමී ලය කුමක්ද?", "දෙගුණ මන්දගාමී ලය (1/2 ගුණය)", "දුගුන් ලය", "තිගුන් ලය", "චෞගුන් ලය", "මාත්‍රා 2ක කාලයක් පුරා එක් බෝල් පදයක් වැයීම ඉතා මන්දගාමී විලම්බිත ලක්ෂණයකි."),
        q("බටහිර සංගීතයේදී සමාන ස්වර දෙකක් (උදා. C සහ C) එකට යා කර එහි කාල ප්‍රමාණය එකතු කරන වක්‍ර රේඛාව කුමක්ද?", "ටයි (Tie)", "ස්ලර් (Slur)", "ස්ටැකාටෝ (Staccato)", "ඩොට් (Dot)", "එකම උසැති ස්වර දෙකක් යා කර තනි දීර්ඝ ස්වරයක් සේ වැයීමට Tie භාවිත කෙරේ."),
        q("සිංහල ජන ගී හා වන්නම් ගායනයේදී තාලය පාලනය කිරීම සඳහා ප්‍රධාන වශයෙන් උපකාරී වන කුඩා ලෝහ භාණ්ඩය කුමක්ද?", "තාලම්පට", "වයලීනය", "සිතාරය", "හොරණෑව", "වන්නම් හා දේශීය නැටුම් ගී තාලය පැහැදිලිව නියාමනය කිරීමට තාලම්පට යොදයි.")
    )
}
